import datetime,gzip,hashlib,json,requests,subprocess,tempfile
ROOT=Path(__file__).resolve().parent
URLS={'wmur-primary': 'https://www.wmur.com/article/new-hampshire-state-primary-election-results-26/73646570', 'nhpr-primary': 'https://www.nhpr.org/elections/primary-2026/results', 'nhpr-primary-liveblog': 'https://www.nhpr.org/live-updates/newhampshire-primary-election-nh-midterm-election-2026', 'wcax-local': 'https://www.wcax.com/politics/local/', 'npr-primary': 'https://apps.npr.org/primary-election-results-2026/states/NH.html', 'sos-results': 'https://www.sos.nh.gov/2026-election-results', 'nh-results-primary': 'https://nhelectionresults.org/results', 'nyt-elections': 'https://www.nytimes.com/section/politics/elections', 'wmur-ap-primary': 'https://interactives.apelections.org/election-results/customers/layouts/organization-layouts/published/63609/32566.html', 'wmur-local-embed': 'https://ehub.htvapps.com/wmur/wp-json/election-hub/v1/iframe-embed/775', 'nhpr-ap-senate': 'https://interactives.apelections.org/election-results/customers/layouts/organization-layouts/published/128298/32161.html', 'nhpr-database': 'https://electiondatabase.nhpr.org/', 'wcax-nh-results': 'https://www.wcax.com/new-hampshire-election-results/', 'wmur-local-widget': 'https://ehub.htvapps.com/wmur/wp-json/election-hub/v1/widget/775', 'conway-home': 'https://www.conwaydailysun.com/', 'conway-primary': 'https://www.conwaydailysun.com/news/local/conway-as-state-goes-for-pappas-sununu-shaheen-dilorenzo/article_59c45c4c-44f3-4ee4-a6f4-23510074db59.html', 'keene-clerk': 'https://keenenh.gov/city-clerk/elections-voting/', 'conway-official-news': 'https://conwaynh.gov/news', 'keene-sentinel-home': 'https://www.keenesentinel.com/', 'seacoast-home': 'https://www.seacoastonline.com/', 'nh-bulletin-primary-turnout': 'https://newhampshirebulletin.com/2026/09/09/in-turnout-tuesday-democrats-outperform-republicans-and-2018/', 'sos-2024-general-index': 'https://www.sos.nh.gov/2024-general-election-results', 'sos-2022-general-index': 'https://www.sos.nh.gov/elections/2022-election-results/2022-general-election-results', 'sos-2020-general-index': 'https://www.sos.nh.gov/elections/2020-election-results/2020-general-election-results', 'sos-2020-senate-pdf': 'https://www.sos.nh.gov/sites/g/files/ehbemt561/files/documents/2020%20GE%20Election%20Tallies/2020-ge-united-states-senate.pdf', 'sos-2024-index-nonwww-alternate': 'https://sos.nh.gov/2024-general-election-results', 'sos-2024-president-indexed-xls': 'https://www.sos.nh.gov/sites/g/files/ehbemt561/files/inline-documents/sonh/2024-ge-president_3.xls', 'nara-2024-index': 'https://www.archives.gov/electoral-college/2024', 'nara-2024-NH-ascertainment': 'https://www.archives.gov/files/electoral-college/2024/ascertainment-new-hampshire.pdf', 'archive-cdx-2024-president-xls': 'https://web.archive.org/cdx/search/cdx?url=https%3A%2F%2Fwww.sos.nh.gov%2Fsites%2Fg%2Ffiles%2Fehbemt561%2Ffiles%2Finline-documents%2Fsonh%2F2024-ge-president_3.xls&output=json&filter=statuscode%3A200&collapse=digest', 'sos-2024-president-archived-original': 'https://web.archive.org/web/20241219142947id_/https://www.sos.nh.gov/sites/g/files/ehbemt561/files/inline-documents/sonh/2024-ge-president_3.xls', 'archive-cdx-2022-senate-discovery': 'https://web.archive.org/cdx/search/cdx?url=www.sos.nh.gov%2F%2A2022%2Asenate%2A&output=json&filter=statuscode%3A200&collapse=urlkey&fl=timestamp%2Coriginal%2Cmimetype%2Cstatuscode%2Cdigest%2Clength', 'archive-cdx-2020-senate-pdf': 'https://web.archive.org/cdx/search/cdx?url=https%3A%2F%2Fwww.sos.nh.gov%2Fsites%2Fg%2Ffiles%2Fehbemt561%2Ffiles%2Fdocuments%2F2020%2520GE%2520Election%2520Tallies%2F2020-ge-united-states-senate.pdf&output=json&filter=statuscode%3A200&collapse=digest', 'sos-2020-senate-archived-original': 'https://web.archive.org/web/20221106132236id_/https://www.sos.nh.gov/sites/g/files/ehbemt561/files/documents/2020%20GE%20Election%20Tallies/2020-ge-united-states-senate.pdf', 'archive-cdx-2022-inline-senate': 'https://web.archive.org/cdx/search/cdx?url=www.sos.nh.gov%2Fsites%2Fg%2Ffiles%2Fehbemt561%2Ffiles%2Finline-documents%2Fsonh%2F2022%2A&output=json&filter=statuscode%3A200&filter=original%3A.%2A%28senate%7Csenator%29.%2A&collapse=urlkey', 'sos-archived-2022-ge-us-senator-remediated-1-pdf': 'https://web.archive.org/web/20230322192318id_/https://www.sos.nh.gov/sites/g/files/ehbemt561/files/inline-documents/sonh/2022-ge-us-senator-remediated_1.pdf', 'sos-archived-2022-ge-us-senator-xls': 'https://web.archive.org/web/20221110130835id_/https://www.sos.nh.gov/sites/g/files/ehbemt561/files/inline-documents/sonh/2022-ge-us-senator.xls', 'sos-archived-2022-ge-us-senator-1-xls': 'https://web.archive.org/web/20221110220908id_/https://www.sos.nh.gov/sites/g/files/ehbemt561/files/inline-documents/sonh/2022-ge-us-senator_1.xls', 'sos-archived-2022-ge-us-senator-2-xls': 'https://web.archive.org/web/20221114154416id_/https://www.sos.nh.gov/sites/g/files/ehbemt561/files/inline-documents/sonh/2022-ge-us-senator_2.xls', 'sos-archived-2022-ge-us-senator-5-xls': 'https://web.archive.org/web/20240114224201id_/https://www.sos.nh.gov/sites/g/files/ehbemt561/files/inline-documents/sonh/2022-ge-us-senator_5.xls', 'berlin-sun-home': 'https://www.berlindailysun.com/', 'laconia-sun-home': 'https://www.laconiadailysun.com/', 'caledonian-record-home': 'https://www.caledonianrecord.com/', 'indepth-home': 'https://indepthnh.org/', 'berlin-ballot-report': 'https://www.berlindailysun.com/berlin_sun/news/local/as-nov-3-election-nears-a-look-at-some-coos-county-ballots/article_a52a83e8-a724-4fa4-a480-245664fc96ba.html', 'laconia-elections-parent': 'https://www.laconiadailysun.com/news/elections', 'laconia-belmont-primary': 'https://www.laconiadailysun.com/news/elections/steady-stream-of-belmont-voters-hit-polls-on-election-day/collection_68c1fba3-3d10-40f5-b42b-9e94f5cf322b.html', 'indepth-absentee-report': 'https://indepthnh.org/2026/10/14/absentee-ballots-for-the-2026-state-general-election-available-for-new-hampshire-voters/'}
def fetch(item):
 key,url=item;row={'id':key,'url':url,'retrieved_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
 try:
  r=requests.get(url,timeout=35);path=ROOT/(key+'.html.gz');path.write_bytes(gzip.compress(r.content,mtime=0))
  row.update(status=r.status_code,final_url=r.url,raw_sha256=hashlib.sha256(r.content).hexdigest(),asset=path.name,stored_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),bytes=len(r.content),headers=dict(r.headers))
 except requests.exceptions.SSLError as e:
  row['requests_error']=str(e)
  with tempfile.TemporaryDirectory() as t:
   body=Path(t)/'body';hdr=Path(t)/'headers'
   c=subprocess.run(['curl','--silent','--show-error','--location','--max-time','35','--dump-header',str(hdr),'--output',str(body),'--write-out','%{http_code}\\n%{url_effective}',url],capture_output=True,text=True)
   row['transport']='system curl with default certificate verification'
   if c.returncode==0:
    code,final=c.stdout.split('\\n',1) if '\\n' in c.stdout else c.stdout.split('\n',1)
    raw=body.read_bytes();path=ROOT/(key+'.html.gz');path.write_bytes(gzip.compress(raw,mtime=0))
    row.update(status=int(code),final_url=final,raw_sha256=hashlib.sha256(raw).hexdigest(),asset=path.name,stored_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),bytes=len(raw),raw_headers=hdr.read_text())
   else:row['error']=c.stderr
 except requests.RequestException as e:row['error']=str(e)
 return row
if __name__=='__main__':
 rows=list(ThreadPoolExecutor(max_workers=4).map(fetch,URLS.items()));(ROOT/'manifest.json').write_text(json.dumps(rows,indent=2)+'\n')
 for r in rows:print(r['id'],r.get('status',r.get('error')))
